$HistoryLength=0;
Module[{start=TimeUsed[],answer},
 answer=TimeConstrained[
  Module[{rr1,rr2,rrD,mm1,mm2,mmD,loss1,lossD},
   rr1=-1/2-((1-b)p+(1+b)q)/2+bp*lam;
   rr2=-((1-b)p(1-p)+(1+b)q(1-q))/4+bp(p-q)+bpp*lam;
   rrD[x_]:=D[x,p]p(1-p)/2+D[x,q]q(1-q)/2+D[x,b]bp+D[x,bp]bpp+D[x,lam](p-q)/2;
   mm1=-bb0-2cc0*ell-bb2*qq+bb1*pp;
   mm2=-2cc0+bb2^2*qq(1-qq)-bb1^2*pp(1-pp);
   mmD[x_]:=D[x,ell]-D[x,pp]bb1*pp(1-pp)-D[x,qq]bb2*qq(1-qq);
   loss1=yy(1+rr+mm);
   lossD=D[loss1,yy]yy(1+rr+mm)+D[loss1,rr]rrp+D[loss1,mm]mmp;
   <|"RR_second_log_residual"->Expand[rrD[rr1]-rr2],
     "Mao_second_log_residual"->Expand[mmD[mm1]-mm2],
     "loss_second_log_residual"->Expand[lossD-yy((1+rr+mm)^2+rrp+mmp)],
     "coalescent_RR_at_u1"->Expand[{rr1,rr2,rr1^2+rr2}/.{p->1/2,q->1/2,lam->0}],
     "numeric_or_IVP_execution"->False|>
  ],0.025,"TIME_LIMIT"];
 <|"kernel_CPU_seconds_observed"->(TimeUsed[]-start),"actual_result"->answer,
 "unmeasured_host_startup_tail"->"UNKNOWN_NOT_ZERO"|>
